import java.util.*;
class TrackedResource implements AutoCloseable {static int openCount;TrackedResource(){openCount++;}void use(){}public void close(){openCount--;}}
public class Main {public static void main(String[] args){int n=new Scanner(System.in).nextInt(),used=0;for(int i=0;i<n;i++){try(TrackedResource r=new TrackedResource()){r.use();used++;}}System.out.println("used="+used+" open="+TrackedResource.openCount);}}
